// deploy.js - CI/CD deployment automation script
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Whitelist of allowed deployment targets
const ALLOWED_TARGETS = new Set(['staging', 'production', 'canary']);

function validateTarget(target) {
  // Input validation: strict whitelist check
  if (!ALLOWED_TARGETS.has(target)) {
    throw new Error(`Invalid deployment target: ${target}`);
  }
  return target;
}

function runDeploymentScript(target) {
  const safeTarget = validateTarget(target);

  // Use execFileSync with argument array - no shell interpretation
  const scriptPath = path.join(__dirname, 'scripts', 'deploy.sh');
  const result = execFileSync(scriptPath, [safeTarget], {
    encoding: 'utf8',
    timeout: 30000,
    stdio: ['pipe', 'pipe', 'pipe']
  });
  return result;
}

function parseConfigFile(filePath) {
  // Read config from a fixed trusted directory only
  const configDir = path.join(__dirname, 'configs');
  const fullPath = path.resolve(configDir, filePath);

  // Ensure the resolved path stays within the config directory
  if (!fullPath.startsWith(configDir)) {
    throw new Error('Path traversal attempt detected');
  }

  const content = fs.readFileSync(fullPath, 'utf8');
  return JSON.parse(content);
}

// Main entry point
try {
  const target = process.argv[2] || 'staging';
  const configFile = process.argv[3] || 'default.json';

  const config = parseConfigFile(configFile);
  console.log(`Deploying to ${target} with config: ${JSON.stringify(config)}`);

  const output = runDeploymentScript(target);
  console.log('Deployment output:', output);

} catch (error) {
  console.error('Deployment failed:', error.message);
  process.exit(1);
}

