import java.util.HashSet;
import java.util.Set;

public class OrderQueryService {

    // 白名单：仅允许预定义的排序字段
    private static final Set<String> ALLOWED_SORT_COLUMNS = 
        new HashSet<>(Arrays.asList("order_id", "created_at", "total_amount"));

    // 白名单：仅允许升序或降序
    private static final Set<String> ALLOWED_SORT_ORDERS = 
        new HashSet<>(Arrays.asList("ASC", "DESC"));

    /**
     * 根据用户输入查询订单，排序字段和排序方向均受白名单约束。
     */
    public String queryOrders(String sortColumn, String sortOrder) throws Exception {
        // 1. 校验排序字段是否在白名单内
        if (!ALLOWED_SORT_COLUMNS.contains(sortColumn)) {
            throw new IllegalArgumentException("Invalid sort column: " + sortColumn);
        }

        // 2. 校验排序方向是否在白名单内
        String normalizedOrder = sortOrder.toUpperCase();
        if (!ALLOWED_SORT_ORDERS.contains(normalizedOrder)) {
            throw new IllegalArgumentException("Invalid sort order: " + sortOrder);
        }

        // 3. 构建安全的 SQL 命令（仅拼接白名单内的常量）
        String[] command = {
            "psql",
            "-c",
            "SELECT * FROM orders ORDER BY " + sortColumn + " " + normalizedOrder
        };

        // 4. 使用 ProcessBuilder 而非 Runtime.exec，避免 shell 解释
        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);

        // 5. 执行命令并读取输出
        Process process = pb.start();
        StringBuilder output = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new RuntimeException("Query failed with exit code: " + exitCode);
        }
        return output.toString();
    }
}

