#define DEVICE_NAME "secure_dev"
#define BUF_SIZE 128

static char *device_buffer;
static int device_open = 0;

static ssize_t device_write(struct file *filp, const char __user *buf,
                            size_t count, loff_t *offset)
{
    size_t copy_len;
    char *temp;

    if (count > BUF_SIZE - 1) {
        pr_err("Write size %zu exceeds limit %d\n", count, BUF_SIZE - 1);
        return -EINVAL;
    }

    temp = kmalloc(count + 1, GFP_KERNEL);
    if (!temp) {
        pr_err("Memory allocation failed\n");
        return -ENOMEM;
    }

    if (copy_from_user(temp, buf, count)) {
        pr_err("Failed to copy data from user\n");
        kfree(temp);
        temp = NULL;
        return -EFAULT;
    }
    temp[count] = '\0';

    mutex_lock(&device_mutex);
    if (device_buffer) {
        kfree(device_buffer);
        device_buffer = NULL;
    }
    device_buffer = temp;
    mutex_unlock(&device_mutex);

    pr_info("Received %zu bytes\n", count);
    return count;
}

static int device_open_handler(struct inode *inode, struct file *filp)
{
    if (device_open) {
        pr_err("Device already open\n");
        return -EBUSY;
    }
    device_open = 1;
    try_module_get(THIS_MODULE);
    return 0;
}

static int device_release_handler(struct inode *inode, struct file *filp)
{
    mutex_lock(&device_mutex);
    if (device_buffer) {
        kfree(device_buffer);
        device_buffer = NULL;
    }
    mutex_unlock(&device_mutex);
    device_open = 0;
    module_put(THIS_MODULE);
    return 0;
}

static struct file_operations fops = {
    .write = device_write,
    .open = device_open_handler,
    .release = device_release_handler,
};

