// routes/passwordReset.js - FastAPI password reset endpoint
const express = require('express');
const router = express.Router();
const crypto = require('crypto');
const db = require('../db');

// Whitelist of valid reset token formats (hex, 32 bytes)
const TOKEN_PATTERN = /^[a-f0-9]{64}$/;

// Simulated token store (in production, use Redis with TTL)
const tokenStore = new Map();

router.post('/reset', async (req, res) => {
  const { email, token, newPassword } = req.body;

  // 1. Validate email format (basic)
  if (!email || !email.includes('@') || email.length > 254) {
    return res.status(400).json({ error: 'Invalid email' });
  }

  // 2. Validate token against strict whitelist pattern
  if (!token || typeof token !== 'string' || !TOKEN_PATTERN.test(token)) {
    return res.status(400).json({ error: 'Invalid token format' });
  }

  // 3. Check token exists and not expired (simulated 15-min TTL)
  const tokenRecord = tokenStore.get(token);
  if (!tokenRecord || tokenRecord.email !== email) {
    return res.status(403).json({ error: 'Token invalid or expired' });
  }
  if (Date.now() - tokenRecord.createdAt > 15 * 60 * 1000) {
    tokenStore.delete(token);
    return res.status(403).json({ error: 'Token expired' });
  }

  // 4. Validate new password strength (min 8 chars, 1 number, 1 uppercase)
  if (!newPassword || newPassword.length < 8 || !/\d/.test(newPassword) || !/[A-Z]/.test(newPassword)) {
    return res.status(400).json({ error: 'Weak password' });
  }

  // 5. Hash the new password with bcrypt (cost factor 12)
  const bcrypt = require('bcrypt');
  const saltRounds = 12;
  const passwordHash = await bcrypt.hash(newPassword, saltRounds);

  // 6. Update password in database using parameterized query
  const updateQuery = 'UPDATE users SET password_hash = $1 WHERE email = $2';
  const result = await db.query(updateQuery, [passwordHash, email]);

  if (result.rowCount === 0) {
    return res.status(404).json({ error: 'User not found' });
  }

  // 7. Invalidate the used token
  tokenStore.delete(token);

  // 8. Log the reset (safe logging, no sensitive data)
  console.log(`Password reset completed for user: ${email}`);

  return res.status(200).json({ message: 'Password reset successful' });
});

module.exports = router;

