@RestController
@RequestMapping("/api/user")
public class UserLogController {
    private static final Logger logger = LoggerFactory.getLogger(UserLogController.class);
    // 白名单：仅允许字母数字下划线，长度1-32
    private static final Pattern SAFE_USERNAME = Pattern.compile("^[a-zA-Z0-9_]{1,32}$");

    @PostMapping("/profile")
    public ModelAndView updateProfile(@RequestParam("username") String username,
                                      HttpServletRequest request) {
        ModelAndView mav = new ModelAndView("profile");

        // 防御1：白名单校验，拒绝一切非法字符
        if (username == null || !SAFE_USERNAME.matcher(username).matches()) {
            logger.warn("Invalid username format from IP: {}", request.getRemoteAddr());
            mav.addObject("error", "Invalid username");
            return mav;
        }

        // 防御2：HTML转义后再拼接日志（双保险，即使白名单被绕过）
        String safeLog = HtmlUtils.htmlEscape(username);
        logger.info("User {} updated profile from IP: {}", safeLog, 
                    request.getRemoteAddr());

        // 业务逻辑：仅记录安全字段
        mav.addObject("username", username);
        return mav;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class OrderQueryService {

    private static final Set<String> ALLOWED_ORDER_STATUS = new HashSet<>(
            Arrays.asList("PENDING", "PAID", "SHIPPED", "COMPLETED", "CANCELLED")
    );

    /**
     * 查询订单列表，基于用户输入的状态过滤。
     * 使用白名单校验防止 OS 命令注入。
     */
    public String queryOrders(String userInputStatus) {
        // 1. 白名单校验：拒绝任何不在允许列表中的输入
        if (!ALLOWED_ORDER_STATUS.contains(userInputStatus)) {
            return "Invalid status. Allowed values: " + ALLOWED_ORDER_STATUS;
        }

        // 2. 构建安全的 shell 命令，输入已通过白名单约束
        String command = "order-cli --status " + userInputStatus + " --format json";

        try {
            Process process = Runtime.getRuntime().exec(new String[]{"sh", "-c", command});

            BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8)
            );

            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                return "Order query failed with exit code: " + exitCode;
            }

            return output.toString().trim();

        } catch (Exception e) {
            return "Error executing order query: " + e.getMessage();
        }
    }
}

// 使用 Spring Boot 框架的 CSRF 防护示例
@RestController
@RequestMapping("/api/account")
public class AccountController {

    @Autowired
    private UserService userService;

    @Autowired
    private CsrfTokenRepository csrfTokenRepository;

    // 登录接口（模拟）
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request, 
                                   HttpServletRequest httpRequest) {
        // 验证 CSRF token（防御措施）
        CsrfToken csrfToken = csrfTokenRepository.loadToken(httpRequest);
        if (csrfToken == null || !csrfToken.getToken().equals(request.getCsrfToken())) {
            throw new InvalidCsrfTokenException("CSRF token mismatch");
        }

        // 业务逻辑：验证用户凭据
        User user = userService.authenticate(request.getUsername(), request.getPassword());
        if (user == null) {
            return ResponseEntity.status(401).body("Invalid credentials");
        }

        // 生成会话 token
        String sessionToken = generateSessionToken(user);
        return ResponseEntity.ok(new LoginResponse(sessionToken));
    }

    // 修改密码接口（敏感操作）
    @PostMapping("/change-password")
    public ResponseEntity<?> changePassword(@RequestBody ChangePasswordRequest request,
                                            HttpServletRequest httpRequest) {
        // 验证 CSRF token（防御措施）
        CsrfToken csrfToken = csrfTokenRepository.loadToken(httpRequest);
        if (csrfToken == null || !csrfToken.getToken().equals(request.getCsrfToken())) {
            throw new InvalidCsrfTokenException("CSRF token mismatch");
        }

        // 业务逻辑：验证旧密码并更新
        User currentUser = getCurrentUser(httpRequest);
        if (!userService.verifyPassword(currentUser, request.getOldPassword())) {
            return ResponseEntity.status(400).body("Old password incorrect");
        }

        userService.updatePassword(currentUser, request.getNewPassword());
        return ResponseEntity.ok("Password updated");
    }

    // 辅助方法：生成会话 token
    private String generateSessionToken(User user) {
        return UUID.randomUUID().toString() + ":" + user.getId();
    }

    // 辅助方法：从请求中获取当前用户
    private User getCurrentUser(HttpServletRequest request) {
        String authHeader = request.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            throw new UnauthorizedException("Missing or invalid auth token");
        }
        String token = authHeader.substring(7);
        return userService.findBySessionToken(token);
    }
}

// kernel_module.cpp - 内核模块内存管理
#include <linux/slab.h>
#include <linux/string.h>
#include <linux/errno.h>
#include <linux/fs.h>

#define MAX_DATA_SIZE 128
#define DEVICE_NAME "secure_dev"

struct device_data {
    char *buffer;
    size_t size;
    struct mutex lock;
    bool is_initialized;
};

static struct device_data *dev_data;

static int device_open(struct inode *inode, struct file *filp) {
    if (!dev_data) {
        dev_data = kzalloc(sizeof(struct device_data), GFP_KERNEL);
        if (!dev_data)
            return -ENOMEM;
        mutex_init(&dev_data->lock);
        dev_data->buffer = kzalloc(MAX_DATA_SIZE, GFP_KERNEL);
        if (!dev_data->buffer) {
            kfree(dev_data);
            dev_data = NULL;
            return -ENOMEM;
        }
        dev_data->size = MAX_DATA_SIZE;
        dev_data->is_initialized = true;
    }
    return 0;
}

static int device_release(struct inode *inode, struct file *filp) {
    if (dev_data) {
        mutex_lock(&dev_data->lock);
        if (dev_data->is_initialized) {
            if (dev_data->buffer) {
                kfree(dev_data->buffer);
                dev_data->buffer = NULL;  // line 36: 置NULL防止悬垂指针
            }
            dev_data->is_initialized = false;
        }
        mutex_unlock(&dev_data->lock);
    }
    return 0;
}

static ssize_t device_write(struct file *filp, const char __user *user_buf,
                            size_t count, loff_t *offset) {
    int ret = 0;
    if (!dev_data || !dev_data->is_initialized)
        return -ENODEV;
    if (count > MAX_DATA_SIZE)
        return -EINVAL;  // line 48: 边界检查防止溢出
    mutex_lock(&dev_data->lock);
    if (copy_from_user(dev_data->buffer, user_buf, count)) {
        ret = -EFAULT;
    } else {
        dev_data->size = count;
        ret = count;
    }
    mutex_unlock(&dev_data->lock);
    return ret;
}

static const struct file_operations fops = {
    .open = device_open,
    .release = device_release,
    .write = device_write,
};

static int __init module_init_fn(void) {
    return register_chrdev(0, DEVICE_NAME, &fops);
}

static void __exit module_exit_fn(void) {
    unregister_chrdev(0, DEVICE_NAME);
    if (dev_data) {
        if (dev_data->buffer) {
            kfree(dev_data->buffer);
            dev_data->buffer = NULL;
        }
        kfree(dev_data);
        dev_data = NULL;  // line 75: 释放后置NULL
    }
}

module_init(module_init_fn);
module_exit(module_exit_fn);
